<script>document.getElementById('beam').addEventListener('submit',async e=>{e.preventDefault();const out=document.getElementById('results'),err=document.getElementById('error');err.textContent='';try{const r=await fetch(@json(route('steel-design.component.crane-beam.calculate')),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});const j=await r.json();if(!r.ok)throw new Error(j.message||'Failed');const table=document.createElement('table');for(const [k,v] of Object.entries(j.section_properties)){const row=table.insertRow();row.insertCell().textContent=k;row.insertCell().textContent=String(v);}out.replaceChildren(table);}catch(ex){out.textContent='No results';err.textContent=ex.message;}});</script></body></html>